<script setup>import {Head,Link,router,useForm} from '@inertiajs/vue3';import AppLayout from '../../../Layouts/AppLayout.vue';import VideoPlayer from '../../../Components/VideoPlayer.vue';const p=defineProps({course:Object,lesson:Object,videos:Array,lessonProgress:Object,watermark:Object,progressConfig:Object});const q=useForm({subject:'',body:'',images:[]});const ask=()=>q.post(`/student/courses/${p.course.id}/lessons/${p.lesson.id}/questions`,{forceFormData:true,onSuccess:()=>q.reset()});const progressUpdate=(v,d)=>{v.progress_percent=d.percent;v.completed=d.completed;if(d.lesson?.completed)p.lessonProgress.completed=true};</script>
<template><AppLayout><Head :title="lesson.title"/><article class="rounded-2xl border bg-white p-4 sm:p-6"><Link :href="`/student/courses/${course.id}`" class="text-sm text-teal-700">بازگشت به دوره</Link><h1 class="mt-5 text-2xl font-bold">{{lesson.title}}</h1><div class="mt-6 min-h-36 whitespace-pre-line leading-8">{{lesson.content}}</div><section v-if="videos.length" class="mt-8 space-y-6 border-t pt-5"><h2 class="font-bold">ویدئوهای درس</h2><article v-for="v in videos" :key="v.id"><div class="flex justify-between"><h3>{{v.title}}</h3><span>{{v.progress_percent}}٪</span></div><VideoPlayer :src="v.stream_url" :title="v.title" :progress-url="v.progress_url" :resume-position="v.resume_position" :watermark="watermark" :heartbeat-seconds="progressConfig.heartbeat_seconds" @progress="progressUpdate(v,$event)"/></article></section><button v-if="lessonProgress.manual_allowed&&!lessonProgress.completed" class="mt-8 rounded-xl bg-teal-700 px-4 py-2 text-white" @click="router.post(`/student/courses/${course.id}/lessons/${lesson.id}/complete`)">علامت‌گذاری به‌عنوان تکمیل‌شده</button><section v-if="lesson.attachments.length" class="mt-8 border-t pt-5"><h2 class="font-bold">فایل‌های درس</h2><a v-for="f in lesson.attachments" :href="`/attachments/${f.id}/download`" class="block p-2 text-teal-700">{{f.original_name}}</a></section><section class="mt-8 border-t pt-5"><h2 class="text-lg font-bold">پرسش و پاسخ</h2><Link v-for="item in lesson.questions" :key="item.id" :href="`/questions/${item.id}`" class="mt-3 block rounded-xl border p-3"><strong>{{item.subject||'بدون موضوع'}}</strong><span class="float-left text-xs">{{item.status}}</span><p class="mt-1 line-clamp-2 text-sm">{{item.body}}</p></Link><form class="mt-5 space-y-3 rounded-xl bg-slate-50 p-4" @submit.prevent="ask"><h3 class="font-bold">پرسش جدید</h3><input v-model="q.subject" placeholder="موضوع (اختیاری)"><textarea v-model="q.body" rows="4" placeholder="متن پرسش" class="w-full rounded-xl border p-3"></textarea><input type="file" multiple accept="image/jpeg,image/png,image/webp" @change="q.images=[...$event.target.files]"><p class="text-xs text-slate-500">حداکثر ۳ تصویر، هرکدام ۵ مگابایت</p><p class="text-sm text-red-600">{{q.errors.body||q.errors.images}}</p><button class="rounded-xl bg-teal-700 px-4 py-2 text-white">ثبت پرسش</button></form></section></article></AppLayout></template>
